<?php
require_once __DIR__ . '/includes/auth.php';
if (!empty($_SESSION['user_id'])) { header('Location: index.php'); exit; }
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $token=(string)($_POST['csrf_token']??'');
 if(empty($_SESSION['csrf_token'])||!hash_equals($_SESSION['csrf_token'],$token)) $error='Sesi berakhir. Muat ulang halaman.';
 else {
  $name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');
  if(mb_strlen($name)<2) $error='Nama minimal 2 karakter.'; elseif(!filter_var($email,FILTER_VALIDATE_EMAIL)) $error='Format email tidak valid.'; elseif(strlen($password)<8) $error='Kata sandi minimal 8 karakter.'; elseif($password!==$confirm) $error='Konfirmasi kata sandi tidak sama.'; else {
   try{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare('INSERT INTO users (full_name,email,password_hash) VALUES (?,?,?)');$stmt->bind_param('sss',$name,$email,$hash);$stmt->execute();$id=(int)$conn->insert_id;$stmt->close();session_regenerate_id(true);$_SESSION['user_id']=$id;$_SESSION['student_name']=$name;$_SESSION['csrf_token']=bin2hex(random_bytes(32));header('Location: index.php?page=profile&welcome=1');exit;}catch(mysqli_sql_exception $ex){$error=$ex->getCode()===1062?'Email tersebut sudah terdaftar.':'Pendaftaran gagal. Pastikan database sudah diimpor.';}
  }
 }
}
